"use client";

import { useState } from 'react';
import { useAuth } from '@/lib/auth-context';
import { DashboardShell } from '@/components/dashboard-shell';

export default function ChangePasswordPage() {
  const { changePassword } = useAuth();
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setLoading(true);
    const { error } = await changePassword(password);
    setLoading(false);
    setMessage(error ? error.message : 'Password updated.');
  };

  return (
    <DashboardShell>
      <div className="rounded-2xl border border-slate-800 bg-slate-900/70 p-6">
        <h2 className="text-2xl font-semibold">Change password</h2>
        <p className="mt-2 text-sm text-slate-400">Set a stronger password for your account.</p>
        <form onSubmit={handleSubmit} className="mt-6 grid gap-4">
          <input type="password" value={password} onChange={(event) => setPassword(event.target.value)} className="rounded-xl border border-slate-700 bg-slate-950 px-4 py-3" placeholder="New password" required />
          <button disabled={loading} className="rounded-xl bg-cyan-500 px-4 py-3 font-medium text-slate-950 transition hover:bg-cyan-400 disabled:opacity-70">
            {loading ? 'Updating…' : 'Update'}
          </button>
          {message ? <p className="text-sm text-slate-300">{message}</p> : null}
        </form>
      </div>
    </DashboardShell>
  );
}
